1	import { describe, it, expect } from "vitest";
2	import { spawn } from "node:child_process";
3	
4	interface CliRun {
5	  stdout: string;
6	  stderr: string;
7	  code: number;
8	}
9	
10	// Spawns the real executable so the tests exercise the actual stdin/stdout and
11	// exit-code contract rather than a stand-in for it.
12	const runCli = (input: string): Promise<CliRun> =>
13	  new Promise((resolve, reject) => {
14	    const cli = spawn("npx", ["tsx", "src/cli.ts"]);
15	    let stdout = "";
16	    let stderr = "";
17	
18	    cli.stdout.on("data", (chunk) => (stdout += chunk));
19	    cli.stderr.on("data", (chunk) => (stderr += chunk));
20	    cli.on("error", reject);
21	    cli.on("close", (code) => resolve({ stdout, stderr, code: code ?? 0 }));
22	
23	    cli.stdin.write(input);
24	    cli.stdin.end();
25	  });
26	
27	const CLI_TIMEOUT_MS = 30_000;
28	
29	describe("claim-office CLI", () => {
30	  it(
31	    "reads a scenario from stdin and writes {results: [...]} to stdout",
32	    async () => {
33	      const { stdout, code } = await runCli(
34	        JSON.stringify({
35	          customer: { yearsWithMHPCO: 0 },
36	          steps: [{ op: "quote", items: [{ type: "sword" }] }],
37	        }),
38	      );
39	
40	      expect(code).toBe(0);
41	      expect(JSON.parse(stdout)).toEqual({ results: [{ premium: 115 }] });
42	    },
43	    CLI_TIMEOUT_MS,
44	  );
45	
46	  it.todo("returns a premium result for a quote step and payout + remainingCap for a claim step (schema example)");
47	  it.todo("exits with a non-zero status and writes to stderr when a quote contains an unknown item type, writing no results to stdout");
48	  it.todo("exits with a non-zero status and writes to stderr when a claim references an item not in the policy");
49	  it.todo("exits with a non-zero status and writes to stderr when a damage amount is negative");
50	});
