1	// How a scenario unfolds. This module knows the order events happen in and
2	// what each step leaves behind for the next one; it delegates what a policy
3	// costs to pricing.ts and what it pays out to coverage.ts.
4	
5	import { premiumFor, type Customer, type Item } from "./pricing.js";
6	import {
7	  capFor,
8	  payoutForDamages,
9	  settleClaim,
10	  type Damage,
11	} from "./coverage.js";
12	import { claimRejection } from "./rejection.js";
13	
14	export type { Customer, KnownItemType } from "./pricing.js";
15	export type { Damage } from "./coverage.js";
16	
17	export interface Scenario {
18	  customer: Customer;
19	  steps: Step[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: { cause: string; damages: Damage[] };
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface ScenarioResults {
36	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
37	}
38	
39	// What earlier steps have established by the time a later step is priced.
40	// Steps are not independent: a quote is a follow-up contract when the customer
41	// already took a quote earlier in the same scenario. Folding this forward —
42	// rather than re-deriving it from the step prefix — is what lets a step read
43	// the state its predecessors left behind.
44	interface Policy {
45	  // The insured items, kept because a claim is settled against them: what a
46	  // damage reimburses depends on the item's own material and enchantment, not
47	  // on the damage entry alone.
48	  items: Item[];
49	  remainingCap: number;
50	}
51	
52	interface ScenarioState {
53	  hasQuoted: boolean;
54	  // Keyed by the step index of the quote that created the policy, which is
55	  // how a later claim step refers to it.
56	  policies: Map<number, Policy>;
57	}
58	
59	const INITIAL_STATE: ScenarioState = { hasQuoted: false, policies: new Map() };
60	
61	type StepOutcome = ScenarioResults["results"][number];
62	
63	interface StepRun {
64	  outcome: StepOutcome;
65	  state: ScenarioState;
66	}
67	
68	// Every policy a step establishes is recorded the same way, so both handlers
69	// go through here rather than each rebuilding the map.
70	const withPolicy = (
71	  state: ScenarioState,
72	  index: number,
73	  policy: Policy,
74	): ScenarioState => ({
75	  ...state,
76	  policies: new Map(state.policies).set(index, policy),
77	});
78	
79	const runQuote = (
80	  { items }: QuoteStep,
81	  customer: Customer,
82	  state: ScenarioState,
83	  index: number,
84	): StepRun => ({
85	  outcome: {
86	    premium: premiumFor(items, {
87	      customer,
88	      isFollowUpContract: state.hasQuoted,
89	    }),
90	  },
91	  state: withPolicy({ ...state, hasQuoted: true }, index, {
92	    items,
93	    remainingCap: capFor(items),
94	  }),
95	});
96	
97	const runClaim = (
98	  { policy: policyIndex, incident }: ClaimStep,
99	  state: ScenarioState,
100	): StepRun => {
101	  // A claim always names a policy an earlier quote step created. No spec
102	  // example covers a claim naming a step that never quoted, so this is not the
103	  // considered answer to that question — but the previous fallback of an empty
104	  // policy was worse than none: it returned a payout of 0 with 0 cap left,
105	  // which is indistinguishable from a real policy that has exhausted its cap.
106	  // A typo'd index read as a legitimate settlement. Fail loudly instead until
107	  // an example says otherwise.
108	  const policy = state.policies.get(policyIndex);
109	  if (policy === undefined) {
110	    throw claimRejection(`names policy ${policyIndex}, which no step created`);
111	  }
112	  const { payout, remainingCap } = settleClaim(
113	    payoutForDamages(policy.items, incident.damages),
114	    policy.remainingCap,
115	  );
116	
117	  return {
118	    outcome: { payout, remainingCap },
119	    state: withPolicy(state, policyIndex, { ...policy, remainingCap }),
120	  };
121	};
122	
123	// Dispatches a step to its handler. Written as an exhaustive switch on `op`
124	// so that adding a step kind to the Step union turns "I forgot to handle it"
125	// into a compile error rather than a wrong number.
126	const runStep = (
127	  step: Step,
128	  customer: Customer,
129	  state: ScenarioState,
130	  index: number,
131	): StepRun => {
132	  switch (step.op) {
133	    case "quote":
134	      return runQuote(step, customer, state, index);
135	    case "claim":
136	      return runClaim(step, state);
137	  }
138	};
139	
140	export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
141	  const { results } = steps.reduce<{
142	    results: StepOutcome[];
143	    state: ScenarioState;
144	  }>(
145	    ({ results, state }, step, index) => {
146	      const stepRun = runStep(step, customer, state, index);
147	      return { results: [...results, stepRun.outcome], state: stepRun.state };
148	    },
149	    { results: [], state: INITIAL_STATE },
150	  );
151	
152	  return { results };
153	};
